    CONSTRAINT authority_window_changes_source_kind_check CHECK ((source_kind = ANY (ARRAY['ibkr_flex_daily'::text, 'ibkr_csv_upload'::text, 'sharekhan_upload'::text, 'dbs_vickers_upload'::text])))
